00, '2012:1356053700:1356054300', 600, 'lt_1h' UNION ALL SELECT 1356054300, 1356054900, '2012:1356054300:1356054900', 600, 'lt_1h' UNION ALL SELECT 1356054900, 1356055500, '2012:1356054900:1356055500', 600, 'lt_1h' UNION ALL SELECT 1356055500, 1356056100, '2012:1356055500:1356056100', 600, 'lt_1h' UNION ALL SELECT 1356056100, 1356056700, '2012:1356056100:1356056700', 600, 'lt_1h' UNION ALL SELECT 1356056700, 1356057300, '2012:1356056700:1356057300', 600, 'lt_1h' UNION ALL SELECT 1356057300, 1356057900, '2012:1356057300:1356057900', 600, 'lt_1h' UNION ALL SELECT 1356057900, 1356058500, '2012:1356057900:1356058500', 600, 'lt_1h' UNION ALL SELECT 1356058500, 1356059100, '2012:1356058500:1356059100', 600, 'lt_1h' UNION ALL SELECT 1356059100, 1356059700, '2012:1356059100:1356059700', 600, 'lt_1h' UNION ALL SELECT 1356059700, 1356060300, '2012:1356059700:1356060300', 600, 'lt_1h' UNION ALL SELECT 1356060300, 1356060900, '2012:1356060300:1356060900', 600, 'lt_1h' UNION ALL SELECT 1356060900, 1356061500, '2012:1356060900:1356061500', 600, 'lt_1h' UNION ALL SELECT 1356061500, 1356062100, '2012:1356061500:1356062100', 600, 'lt_1h' UNION ALL SELECT 1356062100, 1356062700, '2012:1356062100:1356062700', 600, 'lt_1h' UNION ALL SELECT 1356062700, 1356063300, '2012:1356062700:1356063300', 600, 'lt_1h' UNION ALL SELECT 1356063300, 1356063900, '2012:1356063300:1356063900', 600, 'lt_1h' UNION ALL SELECT 1356063900, 1356064500, '2012:1356063900:1356064500', 600, 'lt_1h' UNION ALL SELECT 1356064500, 1356065100, '2012:1356064500:1356065100', 600, 'lt_1h' UNION ALL SELECT 1356065100, 1356065700, '2012:1356065100:1356065700', 600, 'lt_1h' UNION ALL SELECT 1356065700, 1356066300, '2012:1356065700:1356066300', 600, 'lt_1h' UNION ALL SELECT 1356066300, 1356066900, '2012:1356066300:1356066900', 600, 'lt_1h' UNION ALL SELECT 1356066900, 1356067500, '2012:1356066900:1356067500', 600, 'lt_1h' UNION ALL SELECT 1356067500, 1356068100, '2012:1356067500:1356068100', 600, 'lt_1h' UNION ALL SELECT 1356068100, 1356068700, '2012:1356068100:1356068700', 600, 'lt_1h' UNION ALL SELECT 1356068700, 1356069300, '2012:1356068700:1356069300', 600, 'lt_1h' UNION ALL SELECT 1356069300, 1356069900, '2012:1356069300:1356069900', 600, 'lt_1h' UNION ALL SELECT 1356069900, 1356070500, '2012:1356069900:1356070500', 600, 'lt_1h' UNION ALL SELECT 1356070500, 1356071100, '2012:1356070500:1356071100', 600, 'lt_1h' UNION ALL SELECT 1356071100, 1356071700, '2012:1356071100:1356071700', 600, 'lt_1h' UNION ALL SELECT 1356071700, 1356072300, '2012:1356071700:1356072300', 600, 'lt_1h' UNION ALL SELECT 1356072300, 1356072900, '2012:1356072300:1356072900', 600, 'lt_1h' UNION ALL SELECT 1356072900, 1356073500, '2012:1356072900:1356073500', 600, 'lt_1h' UNION ALL SELECT 1356073500, 1356074100, '2012:1356073500:1356074100', 600, 'lt_1h' UNION ALL SELECT 1356074100, 1356074700, '2012:1356074100:1356074700', 600, 'lt_1h' UNION ALL SELECT 1356074700, 1356075300, '2012:1356074700:1356075300', 600, 'lt_1h' UNION ALL SELECT 1356075300, 1356075900, '2012:1356075300:1356075900', 600, 'lt_1h'), wh_hits AS (
 SELECT t.gap_id,t.gap_band,t.left_time,t.right_time,a.dateTime ts,
        a.usUnits wh_units,a.`interval` wh_interval,a.outTemp wh_temp,a.outHumidity wh_rh,
        a.rain wh_rain,a.rainRate wh_rainRate,a.windSpeed wh_wind
 FROM targets t JOIN weewx_WH1080.archive a
   ON a.dateTime>t.left_time AND a.dateTime<t.right_time AND MOD(a.dateTime-t.left_time,300)=0
 LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime
 WHERE r.dateTime IS NULL
)
SELECT CAST(SUBSTRING_INDEX(h.gap_id,':',1) AS UNSIGNED) utc_year,h.gap_band,
 CASE WHEN h.ts>=1514764800 AND h.ts<1522540800 THEN 'PROTECTED_Q1_2018_DIAGNOSTIC' ELSE 'NORMAL' END protection_scope,
 COUNT(*) wh1080_rows,SUM(o.dateTime IS NOT NULL) old_weewx_rows,
 SUM(o.dateTime IS NULL) old_weewx_missing,
 SUM(h.wh_units=17) wh_units17,SUM(h.wh_interval=5) wh_interval5,
 SUM(o.usUnits<=>h.wh_units) units_equal,SUM(o.`interval`<=>h.wh_interval) intervals_equal,
 SUM(o.outTemp<=>h.wh_temp) outTemp_equal,SUM(o.outTemp IS NOT NULL AND h.wh_temp IS NOT NULL) outTemp_both_present,
 SUM(o.outTemp IS NOT NULL AND h.wh_temp IS NOT NULL AND o.outTemp<>h.wh_temp) outTemp_conflict,
 SUM(h.wh_temp=0) wh_outTemp_zero,SUM(h.wh_temp IS NULL) wh_outTemp_null,
 SUM(o.outHumidity<=>h.wh_rh) outHumidity_equal,SUM(o.outHumidity IS NOT NULL AND h.wh_rh IS NOT NULL) outHumidity_both_present,
 SUM(o.outHumidity IS NOT NULL AND h.wh_rh IS NOT NULL AND o.outHumidity<>h.wh_rh) outHumidity_conflict,
 SUM(h.wh_rh IS NULL) wh_outHumidity_null,
 SUM(o.rain<=>h.wh_rain) rain_equal,SUM(o.rain IS NOT NULL AND h.wh_rain IS NOT NULL) rain_both_present,
 SUM(o.rain IS NOT NULL AND h.wh_rain IS NOT NULL AND o.rain<>h.wh_rain) rain_conflict,
 SUM(h.wh_rain IS NULL) wh_rain_null,
 SUM(o.rainRate<=>h.wh_rainRate) rainRate_equal,SUM(o.rainRate IS NOT NULL AND h.wh_rainRate IS NOT NULL) rainRate_both_present,
 SUM(o.rainRate IS NOT NULL AND h.wh_rainRate IS NOT NULL AND o.rainRate<>h.wh_rainRate) rainRate_conflict,
 SUM(h.wh_rainRate IS NULL) wh_rainRate_null,
 SUM(o.windSpeed<=>h.wh_wind) windSpeed_equal,SUM(o.windSpeed IS NOT NULL AND h.wh_wind IS NOT NULL) windSpeed_both_present,
 SUM(o.windSpeed IS NOT NULL AND h.wh_wind IS NOT NULL AND o.windSpeed<>h.wh_wind) windSpeed_conflict,
 SUM(h.wh_wind IS NULL) wh_windSpeed_null
FROM wh_hits h LEFT JOIN old_weewx.archive o ON o.dateTime=h.ts
GROUP BY utc_year,h.gap_band,protection_scope
